-- Weekly Arena 2026-W48: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W48', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-11-23T00:00:00.000Z', '2026-11-30T00:00:00.000Z', 60, 'published', $WK86275ccc780e$[{"id":"wk-2026-w48-01-8fb5","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $28$ and $8$ and each non-parallel side has length $26$. Find its area.","type":"text","correctAnswer":"432","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $10$ and hypotenuse $26$.","solution":"The height is $\\sqrt{26^2-10^2}=24$, so the area is $\\tfrac12(28+8)(24)=432$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w48-02-3951","title":"Sum of Divisors","topic":"Number Theory","level":"Foundation","question":"Find the sum of all positive divisors of $5400$.","type":"text","correctAnswer":"18600","hint":"Factor $N$ into primes; the divisor sum is multiplicative.","solution":"$5400=3^{3}\\cdot 5^{2}\\cdot 2^{3}$, so the divisor sum is $18600$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w48-03-9632","title":"No Neighbouring Ones","topic":"Combinatorics","level":"Intermediate","question":"How many binary strings of length $22$ contain no two consecutive $1$s?","type":"text","correctAnswer":"46368","hint":"Condition on the last digit to get a Fibonacci-type recurrence.","solution":"Let $f(n)=f(n-1)+f(n-2)$ with $f(1)=2$, $f(2)=3$; then $f(22)=46368$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-04-3795","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 4 \\pmod{7}$, $n\\equiv 7 \\pmod{11}$, $n\\equiv 3 \\pmod{5}$.","type":"text","correctAnswer":"18","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $18$ modulo $385$, and $18$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-05-3d3b","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 5$. Find $x^{4} + \\dfrac{1}{x^{4}}$.","type":"text","correctAnswer":"527","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=5T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=5$ the recurrence gives $T_{4}=527$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w48-06-a91b","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $15$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=1$. Find $PA + PB + PT$.","type":"text","correctAnswer":"241","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=15^2/1=225$, so the sum is $1+225+15=241$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w48-07-158c","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $479$ that are divisible by $11$ or by $12$ (or both).","type":"text","correctAnswer":"18974","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $11$, $12$ and $132$ gives $18974$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2026-w48-08-4f13","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $16$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"352","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=16$, i.e. $352$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-09-85ed","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 7t + 4 = 0$. Find the remainder when $r^{7} + s^{7}$ is divided by $1000$.","type":"text","correctAnswer":"643","hint":"Let $S_k=r^k+s^k$. Then $S_k=7S_{k-1}-4S_{k-2}$, with $S_0=2$, $S_1=7$.","solution":"Using $S_k=7S_{k-1}-4S_{k-2}$ from $S_0=2$, $S_1=7$ gives $S_{7}=426643$, whose remainder modulo $1000$ is $643$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w48-10-783d","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 4-tuples $(x_1,\\dots,x_4)$ of non-negative integers satisfy $x_1+\\cdots+x_4=20$ with every $x_i\\le 8$?","type":"text","correctAnswer":"375","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $375$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28}]$WK86275ccc780e$::jsonb
where not exists (select 1 from public.arenas where title = 'Weekly Arena 2026-W48');
